//! Controlled ADR 0156 benchmark fixtures.
//!
//! Candidate-visible task material lives inside a fresh machine-local fixture project. Host-only
//! evaluation reads final fixture/run state and never writes its oracle into a model-readable
//! project, MCP, retrieval, tool-result, or prompt surface.

use crate::agent_benchmark::BenchmarkTaskKind;
use crate::agent_benchmark_campaign::{CampaignFailureKind, CampaignRunRequest};
use crate::agent_host::{AgentRun, AgentRunState, CompletionStatus};
use crate::native_agent::NativeMetrics;
use engine_authoring::{
    initialize_game_project, refresh_game_module_indexes, ProjectConfig, ProjectRoot,
    ProjectSettings, PROJECT_SCHEMA_VERSION,
};
use std::fs;
use std::path::{Path, PathBuf};

const FIXTURE_SCENE_PATH: &str = "scenes/benchmark.scene.json";
const FIXTURE_SOURCE_PATH: &str = "assets/scripts/rust/shared/benchmark_fixture.rs";
const VISIBLE_TASK_FILE: &str = "benchmark-visible-task.json";
const FIXTURE_SCENE: &str = include_str!("agent_benchmark_fixture.scene.json");

#[derive(serde::Serialize)]
struct VisibleTask<'a> {
    task_id: &'a str,
    prompt: &'a str,
    completion_criteria: &'a [String],
    visible_acceptance: &'static str,
}

pub(crate) fn materialize_fixture(
    fixtures_root: &Path,
    request: &CampaignRunRequest,
) -> Result<ProjectRoot, String> {
    let root = fixtures_root
        .join(&request.campaign_fingerprint)
        .join(&request.reset_instance_id);
    if root.exists() {
        fs::remove_dir_all(&root).map_err(|error| error.to_string())?;
    }
    fs::create_dir_all(&root).map_err(|error| error.to_string())?;
    let project = ProjectRoot::create(
        &root,
        ProjectConfig {
            name: "GameEngine ADR0156 Fixture".to_owned(),
            schema_version: PROJECT_SCHEMA_VERSION,
        },
    )
    .map_err(|error| error.to_string())?;
    initialize_game_project(&project).map_err(|error| error.to_string())?;
    fs::write(project.scenes_dir().join("benchmark.scene.json"), FIXTURE_SCENE)
        .map_err(|error| error.to_string())?;
    let mut settings = ProjectSettings::default();
    settings.start_scene = Some(FIXTURE_SCENE_PATH.to_owned());
    settings
        .save(project.path())
        .map_err(|error| error.to_string())?;

    let task = crate::agent_benchmark::benchmark_task(&request.schedule.task_id)
        .ok_or_else(|| format!("unknown benchmark task `{}`", request.schedule.task_id))?;
    let visible = VisibleTask {
        task_id: &request.candidate_contract.task_id,
        prompt: &request.candidate_contract.prompt,
        completion_criteria: &request.candidate_contract.completion_criteria,
        visible_acceptance: visible_acceptance(task.kind),
    };
    fs::write(
        project.path().join(VISIBLE_TASK_FILE),
        serde_json::to_vec_pretty(&visible).map_err(|error| error.to_string())?,
    )
    .map_err(|error| error.to_string())?;

    if matches!(
        task.kind,
        BenchmarkTaskKind::CodeImplementation | BenchmarkTaskKind::ValidationRepair
    ) {
        let source = if task.kind == BenchmarkTaskKind::ValidationRepair {
            "pub fn benchmark_sum(left: i32, right: i32) -> i32 { left + }\n"
        } else {
            "pub fn benchmark_sum(left: i32, right: i32) -> i32 { left - right }\n"
        };
        let source_path = project.path().join(FIXTURE_SOURCE_PATH);
        if let Some(parent) = source_path.parent() {
            fs::create_dir_all(parent).map_err(|error| error.to_string())?;
        }
        fs::write(source_path, source).map_err(|error| error.to_string())?;
        refresh_game_module_indexes(&project).map_err(|error| error.to_string())?;
    }
    Ok(project)
}

fn visible_acceptance(kind: BenchmarkTaskKind) -> &'static str {
    match kind {
        BenchmarkTaskKind::ReadQuestion => {
            "Report the fixture project name, start Scene, and benchmark_target transform with normal source provenance."
        }
        BenchmarkTaskKind::ProjectInspection => {
            "Inspect benchmark_target through governed read-only project/authoring tools; do not mutate the fixture."
        }
        BenchmarkTaskKind::CodeImplementation => {
            "Change benchmark_sum so it returns the mathematical sum of left and right, then pass managed source validation."
        }
        BenchmarkTaskKind::TypedAuthoringMutation => {
            "Rename benchmark_target display_name to `Benchmarked Target` through the typed Editor MCP authoring surface."
        }
        BenchmarkTaskKind::ValidationRepair => {
            "Repair the syntax-invalid benchmark_sum source and pass managed source validation without bypassing the governed workspace."
        }
        BenchmarkTaskKind::RuntimeInteraction => {
            "Launch managed Play and submit at least one deterministic fixed-tick input through the production ADR 0157 runtime-debug surface."
        }
        BenchmarkTaskKind::VisualEvaluation => {
            "Launch managed Play, capture the host-owned Game View frame, and evaluate it only through the production ADR 0157 observation path."
        }
    }
}

pub(crate) fn evaluate_agent_run(
    task: BenchmarkTaskKind,
    fixture_root: &Path,
    run: &AgentRun,
) -> Result<(), CampaignFailureKind> {
    if !matches!(
        run.state,
        AgentRunState::Completed | AgentRunState::Failed | AgentRunState::Cancelled
    ) {
        return Err(CampaignFailureKind::Other);
    }
    match task {
        BenchmarkTaskKind::ReadQuestion => Err(CampaignFailureKind::Other),
        BenchmarkTaskKind::ProjectInspection => {
            (run.audit.authoring_operations == 0
                && run.audit.code_changes == 0
                && run.completion.acceptance_criteria == CompletionStatus::Passed)
                .then_some(())
                .ok_or(CampaignFailureKind::InvalidToolBehavior)
        }
        BenchmarkTaskKind::CodeImplementation => {
            let source = fs::read_to_string(fixture_root.join(FIXTURE_SOURCE_PATH))
                .map_err(|_| CampaignFailureKind::ValidationFailure)?;
            let fixed = source.contains("left + right") || source.contains("right + left");
            (fixed && run.completion.source_validation == CompletionStatus::Passed)
                .then_some(())
                .ok_or(CampaignFailureKind::ValidationFailure)
        }
        BenchmarkTaskKind::TypedAuthoringMutation => {
            let scene = fs::read_to_string(fixture_root.join("assets").join(FIXTURE_SCENE_PATH))
                .map_err(|_| CampaignFailureKind::ValidationFailure)?;
            (scene.contains("\"display_name\": \"Benchmarked Target\"")
                && run.audit.authoring_operations > 0
                && run.completion.authoring_validation == CompletionStatus::Passed)
                .then_some(())
                .ok_or(CampaignFailureKind::ValidationFailure)
        }
        BenchmarkTaskKind::ValidationRepair => {
            let source = fs::read_to_string(fixture_root.join(FIXTURE_SOURCE_PATH))
                .map_err(|_| CampaignFailureKind::ValidationFailure)?;
            (!source.contains("left + }")
                && run.completion.source_validation == CompletionStatus::Passed
                && run.validation_attempts.len() >= 2)
                .then_some(())
                .ok_or(CampaignFailureKind::ValidationFailure)
        }
        BenchmarkTaskKind::RuntimeInteraction => {
            (run.audit.managed_runtime_inputs > 0
                && run.completion.play_launch == CompletionStatus::Passed
                && run.completion.interaction_scenarios == CompletionStatus::Passed)
                .then_some(())
                .ok_or(CampaignFailureKind::RuntimeFailure)
        }
        BenchmarkTaskKind::VisualEvaluation => {
            let visual_completed = matches!(
                run.completion.visual_evaluation,
                CompletionStatus::Passed | CompletionStatus::NotApplicable
            );
            (run.completion.play_launch == CompletionStatus::Passed
                && run.completion.frame_capture == CompletionStatus::Passed
                && visual_completed)
                .then_some(())
                .ok_or(CampaignFailureKind::VisualFailure)
        }
    }
}

pub(crate) fn evaluate_read_question_answer(
    answer: &str,
    metrics: &NativeMetrics,
) -> Result<(), CampaignFailureKind> {
    let normalized = answer.to_ascii_lowercase();
    (metrics.retrieval_chunks > 0
        && normalized.contains("gameengine adr0156 fixture")
        && normalized.contains("benchmark.scene.json")
        && normalized.contains("benchmark_target")
        && normalized.contains("1.0"))
        .then_some(())
        .ok_or(CampaignFailureKind::Other)
}

pub(crate) fn fixture_root(project: &ProjectRoot) -> PathBuf {
    project.path().to_path_buf()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::agent_benchmark::BenchmarkHardwareIdentity;
    use crate::agent_benchmark_campaign::{
        BenchmarkCampaign, BenchmarkCampaignPlan, CampaignCandidate, CampaignCandidateSource,
        CampaignComparisonClass, CampaignEnvironmentIdentity, CampaignExecutionEnvironment,
        CampaignExecutionProfile, CampaignRepresentation, CampaignSeedPolicy, CampaignTaskPlan,
        CAMPAIGN_HARNESS_VERSION, CAMPAIGN_SCHEDULE_VERSION, CAMPAIGN_SCHEMA_VERSION,
    };
    use crate::resource_arbitration::{QualityPreference, TelemetryValue};

    fn request(root_seed: u64) -> CampaignRunRequest {
        let representation = CampaignRepresentation {
            backend_id: "gameengine-managed-llama-cpp".to_owned(),
            model_id: "gguf:fixture".to_owned(),
            model_version: "a".repeat(64),
            quantization: "Q4_K_M".to_owned(),
            representation_size_bytes: 1024,
        };
        let plan = BenchmarkCampaignPlan {
            schema_version: CAMPAIGN_SCHEMA_VERSION,
            corpus_version: crate::agent_benchmark::BENCHMARK_CORPUS_VERSION.to_owned(),
            benchmark_harness_version: crate::agent_benchmark::BENCHMARK_HARNESS_VERSION.to_owned(),
            campaign_harness_version: CAMPAIGN_HARNESS_VERSION.to_owned(),
            schedule_version: CAMPAIGN_SCHEDULE_VERSION.to_owned(),
            candidates: vec![CampaignCandidate {
                representation: representation.clone(),
                source: CampaignCandidateSource::installed(),
            }],
            tasks: vec![CampaignTaskPlan::for_task("code_implementation_v1", root_seed)
                .expect("task")],
            repetitions: 1,
            comparison_class: CampaignComparisonClass::ModelComparison,
            execution_profile: CampaignExecutionProfile::Warm,
            execution_environments: vec![CampaignEnvironmentIdentity {
                environment: CampaignExecutionEnvironment::WindowsNative,
                backend_runtime_version: "runtime-fixture".to_owned(),
            }],
            quality: QualityPreference::Balanced,
            hardware: BenchmarkHardwareIdentity {
                platform: "windows-x86_64".to_owned(),
                gpu: TelemetryValue::Measured("Fixture GPU".to_owned()),
                total_gpu_memory_bytes: TelemetryValue::Measured(1),
                total_system_memory_bytes: TelemetryValue::Measured(1),
            },
            workload_policy_version: crate::agent_benchmark::WORKLOAD_POLICY_VERSION.to_owned(),
            sampling_profile: "fixture".to_owned(),
            seed_policy: CampaignSeedPolicy::Fixed(1),
        };
        let mut campaign = BenchmarkCampaign::new(plan).expect("campaign");
        campaign.start(&[representation]).expect("start");
        campaign
            .begin_next_run()
            .expect("request")
            .expect("scheduled")
    }

    #[test]
    fn fresh_materialization_removes_previous_candidate_mutation() {
        let temp = tempfile::tempdir().expect("temp");
        let request = request(77);
        let first = materialize_fixture(temp.path(), &request).expect("first");
        fs::write(first.path().join(FIXTURE_SOURCE_PATH), "leaked state").expect("mutate");
        let second = materialize_fixture(temp.path(), &request).expect("second");
        let restored = fs::read_to_string(second.path().join(FIXTURE_SOURCE_PATH))
            .expect("source");
        assert!(restored.contains("left - right"));
        assert!(!restored.contains("leaked state"));
    }

    #[test]
    fn candidate_visible_project_contains_no_host_oracle_file() {
        let temp = tempfile::tempdir().expect("temp");
        let request = request(91);
        let project = materialize_fixture(temp.path(), &request).expect("fixture");
        let names = walk_files(project.path());
        assert!(names.iter().any(|path| path.ends_with(VISIBLE_TASK_FILE)));
        assert!(!names.iter().any(|path| {
            let path = path.to_ascii_lowercase();
            path.contains("oracle") || path.contains("golden") || path.contains("answer-key")
        }));
    }

    fn walk_files(root: &Path) -> Vec<String> {
        let mut pending = vec![root.to_path_buf()];
        let mut files = Vec::new();
        while let Some(path) = pending.pop() {
            for entry in fs::read_dir(path).expect("read directory") {
                let entry = entry.expect("entry");
                let path = entry.path();
                if path.is_dir() {
                    pending.push(path);
                } else {
                    files.push(path.to_string_lossy().replace('\\', "/"));
                }
            }
        }
        files
    }
}
